'use strict';
const WF=WorkflowCore,WC=WorkflowConfig;
const wt=(key,params=[])=>I18n.t(key.includes('.')?key:'workflow.'+key,params);
const isWorkflow=(view=state.view)=>view==='recurring'||view==='batch';
state.workflows={recurring:{sources:[],selected:0,settings:WC.settings('recurring'),result:null},batch:{sources:[],selected:0,settings:WC.settings('batch'),result:null}};
function wfLock(){if(isWorkflow())$$('#workspace button,#workspace input,#workspace select').forEach(el=>el.disabled=true);}
function wfState(tool=state.view){return state.workflows[tool];}
function wfSource(){const w=wfState();return w.sources[w.selected]||w.sources[0];}
function wfData(){return wfSource()?.table||null;}
function wfInvalidate(w=wfState()){w.result=null;w.message='workflow.dirty';}
function wfMessage(e){return /^(workflow|recurring|batch)\./.test(e?.message||'')?wt(e.message):wt('genericError');}
function wfEntry(){const w=wfState(),layouts=WF.layouts(w.sources,state.view,true);if(!layouts.length)throw Error(wt('noData'));return {tool:state.view,...layouts[0],layouts};}
function wfApplyPreset(p){const w=wfState();if(!WF.matchLayouts(w.sources,p))throw Error(wt('schemaChanged'));const layouts=p.layouts||[p];for(const s of w.sources)s.mapping=structuredClone(layouts.find(l=>I.match({...l,tool:p.tool},p.tool,s.table.headers)).mapping);w.settings=WC.settings(p.tool,p.settings);wfInvalidate(w);state.appliedPreset=p.name;}
function wfNormalize(tool=state.view){const w=wfState(tool);WF.checkSize(w.sources,tool);return tool==='recurring'?RecurringCore.normalize(w.sources):BatchCore.normalize(w.sources,{targetUnit:w.settings.targetUnit});}
function wfField(key,value,type='text',attrs=''){return `<div><label for="wf-${key}">${esc(wt(key))}</label><input id="wf-${key}" data-wf-setting="${key}" type="${type}" value="${esc(value??'')}" ${attrs}></div>`;}
function wfCheck(key,value){return `<label class="check"><input type="checkbox" data-wf-setting="${key}" ${value?'checked':''}>${esc(wt(key))}</label>`;}
function wfSelect(key,value,entries){return `<div><label for="wf-${key}">${esc(wt(key==='reference'?'referenceBasis':key))}</label><select id="wf-${key}" data-wf-setting="${key}">${entries.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function wfColumn(key,m,s){return `<div><label for="wf-col-${key}">${esc(wt(key))}</label><select id="wf-col-${key}" data-wf-column="${key}"><option value="-1">${esc(wt('none'))}</option>${options(s.table.headers,m[key])}</select></div>`;}
function wfMappingPanel(){const s=wfSource();if(!s)return '';const m=s.mapping,tool=state.view;const cols=tool==='recurring'?(m.format==='wide'?['date','product','lot','equipment']:WC.fields.recurring):WC.fields.batch;
 let body=`<div class="controls">${cols.map(k=>wfColumn(k,m,s)).join('')}</div>`;
 if(tool==='recurring'){body=wfSelect('format',m.format,[['wide',wt('wide')],['long',wt('long')]])+body;if(m.format==='wide')body+=`<h3>${esc(wt('measurements'))}</h3><div class="table-wrap"><table><thead><tr>${['column','name','unit','lsl','usl','remove'].map(k=>`<th>${esc(wt(k))}</th>`).join('')}</tr></thead><tbody>${m.measurements.map((x,i)=>`<tr><td><select aria-label="${esc(wt('column'))}" data-item-index="${i}" data-item-key="column">${options(s.table.headers,x.column)}</select></td>${['name','unit','lsl','usl'].map(k=>`<td><input aria-label="${esc(wt(k))}" data-item-index="${i}" data-item-key="${k}" value="${esc(x[k]??'')}" ${k==='lsl'||k==='usl'?'type="number" step="any"':''}></td>`).join('')}<td><button data-remove-item="${i}" aria-label="${esc(wt('remove'))}">×</button></td></tr>`).join('')}</tbody></table></div><button id="wf-add-item">${esc(wt('addItem'))}</button>`;}
 let preview='';try{const n=tool==='recurring'?RecurringCore.normalize([{...s,table:{...s.table,rows:s.table.rows.slice(0,12)}}]):typeof BatchCore!=='undefined'?BatchCore.normalize([{...s,table:{...s.table,rows:s.table.rows.slice(0,12)}}],{targetUnit:wfState().settings.targetUnit}):{records:[]};const keys=tool==='recurring'?['product','item','lot','equipment','rawValue','unit','lsl','usl']:['product','batch','equipment','step','duration','target'];preview=reportTable(keys.map(k=>wt(k==='rawValue'?'value':k)),n.records.slice(0,12).map(r=>keys.map(k=>r[k])));}catch{preview=`<p>${esc(wt('invalidSettings'))}</p>`;}
 return `<section class="panel"><h2><span class="step">02</span>${esc(wt('review'))}</h2><div class="controls"><div><label for="wf-source">${esc(wt('source'))}</label><select id="wf-source">${wfState().sources.map((x,i)=>`<option value="${i}" ${x===s?'selected':''}>${esc(x.name)} · ${esc(x.sheet)}</option>`).join('')}</select></div><button id="wf-remove">${esc(wt('remove'))}</button></div>${s.headerDetection?.confidence==='low'?`<p class="import-warning">${esc(wt('headerWarning'))}</p>`:''}<details><summary>${esc(wt('header'))} / ${esc(wt('sheet'))}</summary><div class="controls">${s.workbook?`<div><label for="wf-sheet">${esc(wt('sheet'))}</label><select id="wf-sheet">${s.workbook.SheetNames.map(n=>`<option ${n===s.sheet?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`:''}${s.raw?`<div><label for="wf-header">${esc(wt('header'))}</label><input id="wf-header" type="number" min="1" max="${s.raw.length}" value="${s.headerRow}"></div><label class="check"><input type="checkbox" id="wf-has-header" ${s.hasHeader?'checked':''}>${esc(wt('hasHeader'))}</label><button id="wf-remap">${esc(wt('remap'))}</button>`:''}</div></details>${body}<details><summary>${esc(wt('original'))} / ${esc(wt('normalized'))}</summary><h3>${esc(wt('original'))}</h3>${reportTable(s.table.headers,s.table.rows.slice(0,12))}<h3>${esc(wt('normalized'))}</h3>${preview}</details><p class="section-note">${esc(wt('noMutation'))}</p>${preferencesPanel()}</section>`;
}
function wfSettingsPanel(){const w=wfState(),s=w.settings,tool=state.view;
 const fields=tool==='recurring'?['product','item','equipment','lot']:['product','equipment','batch','step'];const suggestions=k=>[...new Set(w.sources.flatMap(src=>k==='item'&&src.mapping.format==='wide'?src.mapping.measurements.map(x=>x.name):src.table.rows.slice(0,1000).map(r=>src.mapping[k]>=0?String(r[src.mapping[k]]??'').trim():'')))].filter(Boolean).slice(0,200);
 let normal=fields.map(k=>wfField(k,s[k],'text',`list="wf-values-${k}"`)+`<datalist id="wf-values-${k}">${suggestions(k).map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`).join('')+['from','to','previousFrom','previousTo'].map(k=>wfField(k,s[k],'date')).join('');
 let advanced=wfField('minSamples',s.minSamples,'number','min="2" max="1000"');
 if(tool==='recurring')advanced+=wfSelect('chart',s.chart,[['imr','Individuals / Moving Range'],['xbar','Xbar-R']])+wfField('subgroupSize',s.subgroupSize,'number','min="2" max="10"')+wfField('cpkThreshold',s.cpkThreshold,'number','min="0" step="any"')+wfField('deltaThreshold',s.deltaThreshold,'number','min="0" step="any"')+wfField('rules',s.rules.join(','))+wfCheck('rationalSubgroups',s.rationalSubgroups)+wfCheck('attentionOos',s.attentionOos)+wfCheck('attentionSpc',s.attentionSpc)+wfCheck('attentionOnly',s.attentionOnly);
 else advanced+=wfSelect('outlier',s.outlier,[['all',wt('includeAll')],['iqr',wt('iqr')]])+wfSelect('targetUnit',s.targetUnit,[['minute',wt('minute')],['hour',wt('hour')]])+wfSelect('displayUnit',s.displayUnit,[['minute',wt('minute')],['hour',wt('hour')]])+wfSelect('reference',s.reference,[['target',wt('targetReference')],['p50',wt('p50Reference')]])+wfSelect('paretoMetric',s.paretoMetric,[['count',wt('count')],['total',wt('total')],['excess',wt('excess')]])+wfSelect('paretoGroup',s.paretoGroup,[['step',wt('step')],['category',wt('category')]]);
 advanced+=wfField('reportTitle',s.reportTitle)+wfField('reportCharts',s.reportCharts,'number','min="0" max="12"');
 return `<section class="panel"><h2><span class="step">03</span>${esc(wt('filters'))}</h2><div class="controls">${normal}</div><div class="load-actions"><button data-period="month">${esc(wt('month'))}</button><button data-period="week">${esc(wt('week'))}</button></div><p class="section-note">${esc(wt('periodHelp'))}</p>${tool==='batch'?`<p class="section-note">${esc(wt('batchHelp'))}</p>`:''}<details><summary>${esc(wt('advanced'))}</summary><div class="controls">${advanced}</div></details><div class="load-actions wf-analysis-actions"><button class="primary" id="wf-analyze">${esc(wt('analyze'))}</button><button id="wf-report" ${w.result?'':'disabled'}>${esc(wt('export'))}</button><span role="status">${esc(w.message?wt(w.message):'')}</span></div></section>`;
}
function renderWorkflow(){const tool=state.view,w=wfState();$('.content').classList.add('capability-wide');$('#eyebrow').textContent=tool==='recurring'?'QUALITY / REVIEW':'OPERATIONS / BATCH';$('#page-title').textContent=wt(tool+'.title');$('#page-description').textContent=wt(tool+'.intro');$$('[data-nav]').forEach(b=>{const active=b.dataset.nav===(tool==='recurring'?'capability':'cycle');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});
 $('#workspace').innerHTML=`<div class="workflow-tabs"><button data-wf-nav="${tool==='recurring'?'capability':'cycle'}">${esc(I18n.t(tool==='recurring'?'shell.554fd5752a':'shell.516db0d1d4'))}</button><strong>${esc(wt(tool+'.title'))}</strong></div><section class="panel"><h2><span class="step">01</span>${esc(wt('upload'))}</h2><div id="wf-drop" class="dropzone"><strong>${esc(wt('drop'))}</strong><button id="wf-upload">${esc(wt('upload'))}</button></div><input type="file" id="wf-files" accept=".xlsx,.xls,.csv,.tsv" multiple hidden><p class="section-note">${esc(wt('limits'))}</p><div class="load-actions"><button id="wf-sample">${esc(wt('sample'))}</button><button id="wf-sample-download">${esc(wt('sampleDownload'))}</button><button id="wf-project-open">${esc(wt('openProject'))}</button><button id="wf-project-save" ${w.sources.length?'':'disabled'}>${esc(wt('saveProject'))}</button></div><input id="wf-project-file" type="file" accept=".mtb,.json" hidden><details><summary>${esc(wt('projectHelp'))}</summary><p>${esc(wt('noMutation'))}</p></details><p id="wf-progress" role="status">${esc(w.sources.length?wt('ready',[w.sources.length,w.sources.reduce((n,s)=>n+s.table.rows.length,0)]):wt('empty'))}</p></section>${wfMappingPanel()}${w.sources.length?wfSettingsPanel():''}<div id="wf-results">${w.result?(tool==='recurring'?renderRecurringResults(w):renderBatchResults(w)):''}</div>`;
 bindWorkflow();if(w.busy)wfLock();if(w.result?.timing)$('#wf-results').insertAdjacentHTML('beforeend',`<p class="section-note">${esc(wt('elapsed',[Math.round((performance.now()-w.startedAt)/1000),Math.round(w.result.timing)]))}</p>`);
}
async function wfReadFiles(files){const tool=state.view,w=wfState(),list=[...files];if(w.busy)return;if(list.length+w.sources.length>20)return toast(wt('limit'));w.busy=true;wfLock();w.startedAt||=performance.now();let errors=0;try{for(let i=0;i<list.length;i++){if(state.view===tool&&$('#wf-progress'))$('#wf-progress').textContent=wt('reading',[i+1,list.length]);await new Promise(r=>setTimeout(r,0));try{const s=await FileReaderCore.read(list[i],XLSX);if(w.sources.reduce((n,x)=>n+x.table.rows.length,0)+s.table.rows.length>50000)throw Error('workflow.limit');s.id='source-'+Date.now()+'-'+i;s.mapping=WF.suggest(tool,s.table);s.table.name=s.name;const saved=preferences.mappings.find(p=>p.tool===tool&&(p.layouts||[p]).some(l=>I.match({...l,tool},tool,s.table.headers)));if(saved)s.mapping=structuredClone((saved.layouts||[saved]).find(l=>I.match({...l,tool},tool,s.table.headers)).mapping);w.sources.push(s);}catch(e){errors++;w.loadError=wfMessage(e);}}w.selected=Math.max(0,w.sources.length-1);wfInvalidate(w);const same=preferences.presets.filter(p=>p.tool===tool&&p.auto&&WF.matchLayouts(w.sources,p));if(same.length===1&&state.view===tool)wfApplyPreset(same[0]);else if(preferences.presets.some(p=>p.tool===tool&&p.auto)&&same.length===0)w.message='workflow.schemaChanged';}finally{w.busy=false;if(state.view===tool){render();if(errors)toast(w.loadError);}}}
function bindWorkflow(){const w=wfState(),tool=state.view;
 $$('[data-wf-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.wfNav));$('#wf-upload').onclick=()=>$('#wf-files').click();$('#wf-files').onchange=e=>wfReadFiles(e.target.files);const dz=$('#wf-drop');dz.ondragover=e=>{e.preventDefault();dz.classList.add('dragover');};dz.ondragleave=()=>dz.classList.remove('dragover');dz.ondrop=e=>{e.preventDefault();wfReadFiles(e.dataTransfer.files);};$('#wf-sample').onclick=()=>{const ss=wfSampleSources(tool);w.sources=ss;w.selected=0;w.settings=WC.settings(tool);w.startedAt=performance.now();wfInvalidate(w);state.appliedPreset='';render();};$('#wf-sample-download').onclick=()=>safe(()=>saveWorkbook(wfSampleSources(tool).map((s,i)=>['Sample'+(i+1),[s.table.headers,...s.table.rows]]),tool+'-sample.xlsx'));
 $('#wf-project-save').onclick=()=>safe(()=>{try{const p=WF.project(tool,w.sources,w.settings);saveBlob(JSON.stringify(p),tool+'-project.mtb','application/json');}catch(e){throw Error(wfMessage(e));}});$('#wf-project-open').onclick=()=>$('#wf-project-file').click();$('#wf-project-file').onchange=async e=>{if(w.busy)return;const f=e.target.files[0];if(!f)return;const navigation=state.navigationVersion||0;w.busy=true;wfLock();try{if(f.size>50*1024*1024)throw Error('workflow.limit');const p=WF.validateProject(JSON.parse(await f.text()));if(state.view!==tool||(state.navigationVersion||0)!==navigation)throw Error('workflow.importCancelled');const target=wfState(p.tool);if(target!==w&&target.busy)throw Error('workflow.importCancelled');target.sources=p.sources;target.selected=0;target.settings=p.settings;target.startedAt=performance.now();wfInvalidate(target);w.busy=false;navigate(p.tool);}catch(e){toast(wfMessage(e));}finally{w.busy=false;if(state.view===tool)render();}};
 if(!w.sources.length)return;$('#wf-source').onchange=e=>{w.selected=Number(e.target.value);render();};$('#wf-remove').onclick=()=>{w.sources.splice(w.selected,1);w.selected=0;wfInvalidate(w);render();};
 $$('[data-wf-column]').forEach(el=>el.onchange=()=>{wfSource().mapping[el.dataset.wfColumn]=Number(el.value);wfInvalidate(w);render();});
 if($('#wf-format'))$('#wf-format').onchange=e=>{const m=wfSource().mapping;m.format=e.target.value;if(!m.measurements?.length)m.measurements=I.infer(wfSource().table).filter(x=>x.type==='number').map(x=>({column:x.index,name:wfSource().table.headers[x.index],unit:'',lsl:null,usl:null}));wfInvalidate(w);render();};
 $$('[data-item-key]').forEach(el=>el.onchange=()=>{const x=wfSource().mapping.measurements[Number(el.dataset.itemIndex)],k=el.dataset.itemKey;x[k]=k==='column'?Number(el.value):k==='lsl'||k==='usl'?el.value===''?null:Number(el.value):el.value;wfInvalidate(w);render();});
 $$('[data-remove-item]').forEach(el=>el.onclick=()=>{wfSource().mapping.measurements.splice(Number(el.dataset.removeItem),1);wfInvalidate(w);render();});if($('#wf-add-item'))$('#wf-add-item').onclick=()=>{const s=wfSource(),taken=new Set(s.mapping.measurements.map(x=>x.column)),i=s.table.headers.findIndex((_,i)=>!taken.has(i)&&!['date','product','lot','equipment'].some(k=>s.mapping[k]===i));if(i>=0)s.mapping.measurements.push({column:i,name:s.table.headers[i],unit:'',lsl:null,usl:null});wfInvalidate(w);render();};
 const commitTable=(s,updates)=>{const candidate={...s,...updates};candidate.table=C.table(candidate.raw.slice(candidate.headerRow-1),candidate.hasHeader);Object.assign(candidate.table,{name:candidate.name,date1904:candidate.date1904,sourceHeaderRow:candidate.headerRow,sourceHasHeader:candidate.hasHeader,sheet:candidate.sheet});candidate.mapping=WF.suggest(tool,candidate.table);WF.checkSize(w.sources.map(x=>x===s?candidate:x),tool);Object.assign(s,candidate);wfInvalidate(w);};
 const remap=()=>{try{const s=wfSource(),headerRow=Number($('#wf-header').value);if(!Number.isInteger(headerRow)||headerRow<1||headerRow>s.raw.length)throw Error('workflow.invalidSettings');commitTable(s,{headerRow,hasHeader:$('#wf-has-header').checked,headerDetection:null});render();}catch(e){render();toast(wfMessage(e));}};if($('#wf-remap'))$('#wf-remap').onclick=remap;
 if($('#wf-sheet'))$('#wf-sheet').onchange=e=>{try{const s=wfSource(),sheet=e.target.value,raw=FileReaderCore.quietVendor(()=>I.sheetRows(XLSX,s.workbook.Sheets[sheet])),headerDetection=C.detectHeader(raw);commitTable(s,{sheet,raw,headerDetection,headerRow:headerDetection.headerRow,hasHeader:headerDetection.hasHeader});render();}catch(e){render();toast(wfMessage(e));}};
 $$('[data-wf-setting]').filter(el=>el.dataset.wfSetting!=='format').forEach(el=>el.onchange=()=>{const k=el.dataset.wfSetting;w.settings[k]=el.type==='checkbox'?el.checked:el.type==='number'?el.value===''?null:Number(el.value):k==='rules'?el.value.split(',').filter(x=>x.trim()).map(Number):el.value;wfInvalidate(w);render();});
 $$('[data-period]').forEach(el=>el.onclick=()=>safe(()=>{const records=wfNormalize().records;Object.assign(w.settings,WF.period(el.dataset.period,records));wfInvalidate(w);render();}));
 $('#wf-analyze').onclick=()=>wfAnalyze(tool);$('#wf-report').onclick=()=>safe(()=>openReport(tool));bindPreferences();if(tool==='batch')bindBatchResults();else bindWorkflowResults();
}
async function wfAnalyze(tool){const w=wfState(tool);if(w.busy)return;w.busy=true;wfLock();if($('#wf-analyze')){$('#wf-analyze').disabled=true;$('#wf-analyze').textContent=wt('busy');}await new Promise(r=>setTimeout(r,0));try{const settings=WC.settings(tool,w.settings);WF.layouts(w.sources,tool);const start=performance.now(),n=wfNormalize(tool);if(n.records.length>200000)throw Error('workflow.limit');const result=tool==='recurring'?RecurringCore.analyze(n.records,settings):BatchCore.analyze(n.records,settings);result.normalized=n;result.timing=performance.now()-start;w.result=result;w.settings=settings;w.message='';}catch(e){w.message='workflow.invalidSettings';toast(wfMessage(e));}finally{w.busy=false;if(state.view===tool)render();}}
function wfSampleSources(tool){if(tool==='batch')return batchSampleSources();const headers=['Date','Product','Lot','Equipment','Viscosity','Volatile'];return ['2026-09','2026-10'].map((month,j)=>{const table={headers,rows:Array.from({length:64},(_,i)=>[`${month}-${String(1+i%20).padStart(2,'0')}`,'DEMO-'+(i<32?'A':'B'),`L${i+1+j*64}`,'DEMO-R1',Number((102+Math.sin(i*1.6)*2+j*1.5+(i===60?9:0)).toFixed(3)),Number((.8+Math.sin(i*.9)*.1).toFixed(3))]),sourceHeaderRow:1,sourceHasHeader:true};const mapping=WF.suggest(tool,table);mapping.measurements[0].unit='mPa·s';mapping.measurements[0].lsl=95;mapping.measurements[0].usl=110;mapping.measurements[1].unit='%';mapping.measurements[1].usl=1.1;return {id:'demo-'+j,name:month+'-synthetic.xlsx',sheet:'Inspection',date1904:false,isDemo:true,table,mapping};});}
function workflowLinks(){return `<section class="panel wf-home"><h2>${esc(wt('title'))}</h2><div class="tool-cards">${['recurring','batch'].map(k=>`<button class="tool-card" data-wf-nav="${k}"><h3>${esc(wt(k+'.title'))}</h3><p>${esc(wt(k+'.intro'))}</p><span>${esc(wt('analyze'))} →</span></button>`).join('')}</div></section>`;}
function bindWorkflowLinks(){$$('[data-wf-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.wfNav));}
